WITH gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM payments), islands AS (SELECT id, method, amount, paid_at, status, SUM(is_new_burst) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT id, status, CASE WHEN status RLIKE '^(REFUNDED|SUCCESS)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS status_zone FROM islands ORDER BY status_zone
